<template>
  <div class="sg-client-page sg3-utility-page sg-wallet-page">
    <PublicNavbar />
    <main class="sg3-container sg3-profile-main">
      <header class="sg3-page-head">
        <div>
          <div class="sg3-breadcrumbs"><router-link to="/profile">Tài khoản</router-link><span>/</span><strong>Ví SportGo</strong></div>
          <p class="sg3-kicker">Ví và thanh toán</p>
          <h1>Ví SportGo</h1>
          <p>Quản lý số dư, lịch sử hoàn tiền và yêu cầu chuyển tiền về tài khoản ngân hàng.</p>
        </div>
        <div class="sg-wallet-head-actions">
          <button class="sg3-button sg3-button--secondary" type="button" @click="openAccountManager">
            <AppIcon name="building" :size="16" /> Quản lý tài khoản
          </button>
          <button class="sg3-button sg3-button--primary" type="button" @click="openWithdrawalModal">
            <AppIcon name="banknote" :size="16" /> Yêu cầu rút tiền
          </button>
        </div>
      </header>

      <form class="sg-wallet-ledger-filters" @submit.prevent="applyLedgerFilters">
        <select v-model="ledgerFilters.type"><option value="">Tất cả loại giao dịch</option><option value="deposit">Nạp tiền</option><option value="payment">Thanh toán</option><option value="refund">Hoàn tiền</option><option value="withdrawal">Rút tiền</option><option value="adjustment">Điều chỉnh</option></select>
        <select v-model="ledgerFilters.status"><option value="">Tất cả trạng thái</option><option value="completed">Hoàn tất</option><option value="pending">Đang xử lý</option><option value="failed">Thất bại</option><option value="cancelled">Đã hủy</option></select>
        <button class="sg3-button sg3-button--secondary" type="submit" :disabled="loading || refreshing"><AppIcon name="filter" :size="15" /> {{ loading || refreshing ? 'Đang lọc...' : 'Lọc sổ giao dịch' }}</button>
      </form>

      <p v-if="actionError && !withdrawalOpen && !accountOpen" class="sg-wallet-inline-error" role="alert">{{ actionError }}</p>

      <div v-if="loading && !walletLoaded" class="sg3-empty"><div><strong>Đang tải ví SportGo</strong><p>Đang đồng bộ số dư và giao dịch của bạn.</p></div></div>
      <div v-else-if="error" class="sg3-error"><div><strong>Không tải được ví</strong><p>{{ error }}</p><button class="sg3-button sg3-button--primary" type="button" @click="loadWallet">Thử lại</button></div></div>
      <template v-else>
        <section class="sg-wallet-balance-card"><div><span>Số dư có thể sử dụng</span><strong>{{ money(wallet.balance) }}</strong><small>Hoàn tiền sẽ được cộng vào ví sau khi hoàn tất đối soát.</small></div><div class="sg-wallet-balance-side"><span>Đang giữ</span><strong>{{ money(wallet.locked_balance) }}</strong><em :class="`is-${wallet.status}`">{{ statusLabel(wallet.status) }}</em></div></section>
        <section class="sg-wallet-insight-grid"><article class="sg3-card"><span class="sg-wallet-insight-icon"><AppIcon name="rotateCcw" :size="17" /></span><div><small>Tổng giao dịch</small><strong>{{ ledgers.length }}</strong><span>biến động gần nhất</span></div></article><article class="sg3-card"><span class="sg-wallet-insight-icon is-amber"><AppIcon name="clock" :size="17" /></span><div><small>Yêu cầu rút đang xử lý</small><strong>{{ pendingWithdrawals }}</strong><span>yêu cầu chờ duyệt</span></div></article><article class="sg3-card"><span class="sg-wallet-insight-icon is-blue"><AppIcon name="building" :size="17" /></span><div><small>Tài khoản nhận tiền</small><strong>{{ payoutAccounts.length }}</strong><span>{{ defaultAccountLabel }}</span></div></article></section>
        <section class="sg-wallet-content-grid"><section class="sg3-card sg-wallet-ledger"><header class="sg-wallet-section-head"><div><p class="sg3-kicker">Dòng tiền</p><h2>Lịch sử ví</h2><span>Các khoản thanh toán, hoàn tiền và điều chỉnh mới nhất.</span></div><button class="sg3-button sg3-button--secondary" type="button" :disabled="refreshing" @click="loadWallet"><AppIcon name="refresh" :size="15" /> {{ refreshing ? 'Đang tải...' : 'Làm mới' }}</button></header><div v-if="!ledgers.length" class="sg-wallet-empty"><AppIcon name="wallet" :size="25" /><strong>Ví chưa có giao dịch</strong><p>Các biến động sẽ xuất hiện tại đây.</p></div><div v-else class="sg-wallet-ledger-table"><div class="sg-wallet-table-head"><span>Giao dịch</span><span>Số tiền</span><span>Số dư sau</span></div><article v-for="ledger in ledgers" :key="ledger.id"><div><span class="sg-wallet-ledger-icon" :class="ledger.direction"><AppIcon :name="ledger.direction === 'credit' ? 'rotateCcw' : 'banknote'" :size="15" /></span><div><strong>{{ ledger.note || typeLabel(ledger.type) }}</strong><small>{{ ledger.transaction_code || 'Giao dịch SportGo' }} · {{ formatDate(ledger.created_at) }}</small></div></div><strong :class="ledger.direction">{{ ledger.direction === 'credit' ? '+' : '-' }}{{ money(ledger.amount) }}</strong><span>{{ money(ledger.balance_after) }}</span></article></div></section>
          <aside class="sg-wallet-side"><section class="sg3-card sg-wallet-withdrawals"><header class="sg-wallet-section-head"><div><p class="sg3-kicker">Theo dõi chi trả</p><h2>Yêu cầu rút tiền</h2></div><button class="sg3-button sg3-button--quiet" type="button" @click="openWithdrawalModal">Tạo mới</button></header><div v-if="!withdrawals.length" class="sg-wallet-empty sg-wallet-empty--small"><AppIcon name="banknote" :size="23" /><strong>Chưa có yêu cầu</strong><p>Chuyển tiền từ ví về tài khoản ngân hàng của bạn.</p></div><article v-for="withdrawal in withdrawals" :key="withdrawal.id" class="sg-wallet-withdrawal-row"><div><strong>{{ money(withdrawal.amount) }}</strong><span>{{ withdrawal.payout_account?.bank_name || 'Tài khoản nhận tiền' }} · {{ withdrawal.payout_account?.bank_account_masked || '' }}</span><small>{{ formatDate(withdrawal.requested_at) }}</small></div><div><em :class="`is-${withdrawal.status}`">{{ withdrawal.status_label }}</em><button v-if="withdrawal.status === 'pending'" type="button" :disabled="processingWithdrawalId === withdrawal.id" @click="cancelWithdrawal(withdrawal)">{{ processingWithdrawalId === withdrawal.id ? 'Đang hủy...' : 'Hủy yêu cầu' }}</button></div><p v-if="withdrawal.rejected_reason">{{ withdrawal.rejected_reason }}</p></article></section><section class="sg3-card sg-wallet-help"><AppIcon name="shieldCheck" :size="20" /><div><strong>Rút tiền an toàn</strong><p>Số tiền sẽ được giữ trong lúc chờ duyệt. Bạn có thể hủy khi yêu cầu còn ở trạng thái chờ.</p></div></section></aside></section>
      </template>

      <div v-if="withdrawalOpen" class="sg-wallet-modal-backdrop" @click.self="withdrawalOpen = false"><section class="sg-wallet-modal" role="dialog" aria-modal="true" aria-labelledby="withdrawal-title"><header><div><p class="sg3-kicker">Chuyển tiền về ngân hàng</p><h2 id="withdrawal-title">Yêu cầu rút tiền</h2></div><button type="button" aria-label="Đóng" @click="withdrawalOpen = false"><AppIcon name="x" :size="18" /></button></header><div class="sg-wallet-modal-body"><div class="sg-wallet-modal-balance"><span>Số dư có thể rút</span><strong>{{ money(wallet.balance) }}</strong></div><p v-if="Number(wallet.balance) < 10000" class="sg-wallet-modal-note">Số dư tối thiểu để rút là 10.000đ. Bạn có thể quay lại sau khi ví có thêm số dư.</p><label class="sg3-field"><span>Số tiền muốn rút</span><input v-model.number="withdrawalForm.amount" type="number" min="10000" :max="wallet.balance" step="1000" placeholder="10000" /><small>Tối thiểu 10.000đ và không vượt quá số dư khả dụng.</small></label><label class="sg3-field"><span>Tài khoản nhận tiền</span><select v-model="withdrawalForm.payout_account_id"><option value="">Chọn tài khoản ngân hàng</option><option v-for="account in payoutAccounts" :key="account.id" :value="account.id">{{ account.bank_name }} · {{ account.bank_account_masked }} · {{ account.bank_account_holder }}</option></select></label><p v-if="!payoutAccounts.length" class="sg-wallet-modal-note">Bạn chưa có tài khoản nhận tiền. Hãy đóng cửa sổ này, mở “Quản lý tài khoản” và thêm tài khoản trước.</p><p v-if="actionError" class="sg-wallet-action-error">{{ actionError }}</p></div><footer><button class="sg3-button sg3-button--secondary" type="button" @click="withdrawalOpen = false">Đóng</button><button class="sg3-button sg3-button--primary" type="button" :disabled="saving || Number(wallet.balance) < 10000 || !withdrawalForm.payout_account_id || Number(withdrawalForm.amount) < 10000 || Number(withdrawalForm.amount) > Number(wallet.balance)" @click="requestWithdrawal">{{ saving ? 'Đang gửi...' : 'Gửi yêu cầu' }}</button></footer></section></div>

      <div v-if="accountOpen" class="sg-wallet-modal-backdrop" @click.self="closeAccountModal"><section class="sg-wallet-modal sg-wallet-account-modal" role="dialog" aria-modal="true" aria-labelledby="account-title"><header><div><p class="sg3-kicker">Thông tin chi trả</p><h2 id="account-title">Tài khoản nhận tiền</h2></div><button type="button" aria-label="Đóng" @click="closeAccountModal"><AppIcon name="x" :size="18" /></button></header><div class="sg-wallet-modal-body"><div class="sg-wallet-account-toolbar"><div><strong>{{ payoutAccounts.length }} tài khoản đang hoạt động</strong><span>Chọn tài khoản mặc định để nhận tiền nhanh hơn.</span></div><button v-if="!accountFormOpen" class="sg3-button sg3-button--primary" type="button" @click="startAccountForm"><AppIcon name="plus" :size="15" /> Thêm tài khoản</button></div><div v-if="payoutAccounts.length" class="sg-wallet-existing-accounts"><article v-for="account in payoutAccounts" :key="account.id" class="sg-wallet-account-row"><div><span v-if="account.is_default" class="sg-wallet-default">Mặc định</span><strong>{{ account.bank_name }}</strong><small>{{ account.bank_account_masked }} · {{ account.bank_account_holder }}</small><small v-if="account.bank_branch">{{ account.bank_branch }}</small></div><div class="sg-wallet-account-actions"><button type="button" @click="editAccount(account)"><AppIcon name="edit" :size="15" /> Sửa</button><button type="button" class="is-danger" :disabled="deletingAccountId === account.id" @click="deleteAccount(account)"><AppIcon name="trash" :size="15" /> {{ deletingAccountId === account.id ? 'Đang xóa...' : 'Xóa' }}</button></div></article></div><div v-else class="sg-wallet-empty sg-wallet-empty--small"><AppIcon name="building" :size="24" /><strong>Chưa có tài khoản nhận tiền</strong><p>Thêm một tài khoản ngân hàng để sử dụng yêu cầu rút tiền.</p></div><form v-if="accountFormOpen" class="sg-wallet-account-form" @submit.prevent="saveAccount"><div class="sg-wallet-form-heading"><strong>{{ accountForm.id ? 'Chỉnh sửa tài khoản' : 'Thêm tài khoản mới' }}</strong><button type="button" @click="accountFormOpen = false">Đóng form</button></div><label class="sg3-field"><span>Ngân hàng</span><input v-model.trim="accountForm.bank_name" required placeholder="Ví dụ: Vietcombank" /></label><div class="sg-wallet-modal-fields"><label class="sg3-field"><span>Số tài khoản</span><input v-model.trim="accountForm.bank_account_number" required inputmode="numeric" /></label><label class="sg3-field"><span>Chủ tài khoản</span><input v-model.trim="accountForm.bank_account_holder" required /></label></div><label class="sg3-field"><span>Chi nhánh</span><input v-model.trim="accountForm.bank_branch" /></label><label class="sg-wallet-check"><input v-model="accountForm.is_default" type="checkbox" /> Đặt làm tài khoản mặc định</label><p v-if="actionError" class="sg-wallet-action-error">{{ actionError }}</p><footer><button class="sg3-button sg3-button--secondary" type="button" @click="accountFormOpen = false">Hủy</button><button class="sg3-button sg3-button--primary" type="submit" :disabled="saving">{{ saving ? 'Đang lưu...' : 'Lưu tài khoản' }}</button></footer></form></div></section></div>
    </main>
  </div>
</template>

<script>
import AppIcon from '../../components/AppIcon.vue';
import PublicNavbar from '../../components/PublicNavbar.vue';
import { walletService } from '../../services/walletService.js';

const emptyForm = () => ({ id: null, bank_name: '', bank_account_number: '', bank_account_holder: '', bank_branch: '', is_default: true });
export default {
  name: 'ClientWallet', components: { AppIcon, PublicNavbar },
  data() { return { wallet: { balance: 0, locked_balance: 0, status: 'active' }, ledgers: [], payoutAccounts: [], withdrawals: [], loading: true, walletLoaded: false, refreshing: false, error: '', saving: false, actionError: '', withdrawalOpen: false, accountOpen: false, accountFormOpen: false, deletingAccountId: null, processingWithdrawalId: null, walletRequestId: 0, withdrawalForm: { amount: '', payout_account_id: '' }, accountForm: emptyForm(), ledgerFilters: { type: '', status: '' } }; },
  computed: { pendingWithdrawals() { return this.withdrawals.filter((item) => ['pending', 'approved'].includes(item.status)).length; }, defaultAccountLabel() { const account = this.payoutAccounts.find((item) => item.is_default) || this.payoutAccounts[0]; return account ? `${account.bank_name} · ${account.bank_account_masked}` : 'Chưa thêm tài khoản'; } },
  mounted() { this.loadWallet(); },
  methods: {
    async loadWallet() { const requestId = ++this.walletRequestId; this.loading = !this.walletLoaded; this.refreshing = this.walletLoaded; this.error = ''; try { const response = await walletService.show({ ledger_type: this.ledgerFilters.type, ledger_status: this.ledgerFilters.status }); if (requestId !== this.walletRequestId) return; this.wallet = response.wallet || this.wallet; this.ledgers = Array.isArray(response.ledgers) ? response.ledgers : []; this.payoutAccounts = Array.isArray(response.payout_accounts) ? response.payout_accounts : []; this.withdrawals = Array.isArray(response.withdrawals) ? response.withdrawals : []; this.walletLoaded = true; } catch (error) { if (requestId === this.walletRequestId) this.error = error.message || 'Không thể tải thông tin ví.'; } finally { if (requestId === this.walletRequestId) { this.loading = false; this.refreshing = false; } } },
    applyLedgerFilters() { if (!this.loading) this.loadWallet(); },
    openWithdrawalModal() { this.actionError = ''; const account = this.payoutAccounts.find((item) => item.is_default) || this.payoutAccounts[0]; this.withdrawalForm = { amount: '', payout_account_id: account?.id || '' }; this.withdrawalOpen = true; },
    async requestWithdrawal() { if (this.saving || Number(this.wallet.balance) < 10000) return; this.saving = true; this.actionError = ''; try { await walletService.requestWithdrawal({ amount: Number(this.withdrawalForm.amount), payout_account_id: Number(this.withdrawalForm.payout_account_id) }); this.withdrawalOpen = false; this.withdrawalForm = { amount: '', payout_account_id: '' }; await this.loadWallet(); } catch (error) { this.actionError = error.message || 'Không thể gửi yêu cầu rút tiền.'; } finally { this.saving = false; } },
    openAccountManager() { this.accountOpen = true; this.accountFormOpen = false; this.accountForm = emptyForm(); this.actionError = ''; },
    startAccountForm() { this.accountForm = emptyForm(); this.accountFormOpen = true; this.actionError = ''; },
    async saveAccount() { if (this.saving) return; this.saving = true; this.actionError = ''; try { await walletService.savePayoutAccount(this.accountForm); this.accountForm = emptyForm(); this.accountFormOpen = false; await this.loadWallet(); } catch (error) { this.actionError = error.message || 'Không thể lưu tài khoản nhận tiền.'; } finally { this.saving = false; } },
    editAccount(account) { this.accountForm = { id: account.id, bank_name: account.bank_name, bank_account_number: account.bank_account_number || '', bank_account_holder: account.bank_account_holder, bank_branch: account.bank_branch || '', is_default: account.is_default }; this.accountFormOpen = true; this.actionError = ''; },
    async deleteAccount(account) { if (!account?.id || this.deletingAccountId) return; if (!window.confirm(`Xóa tài khoản ${account.bank_name} · ${account.bank_account_masked}?`)) return; this.deletingAccountId = account.id; this.actionError = ''; try { await walletService.deletePayoutAccount(account.id); if (this.accountForm.id === account.id) { this.accountForm = emptyForm(); this.accountFormOpen = false; } await this.loadWallet(); } catch (error) { this.actionError = error.message || 'Không thể xóa tài khoản nhận tiền.'; } finally { this.deletingAccountId = null; } },
    closeAccountModal() { if (this.saving || this.deletingAccountId) return; this.accountOpen = false; this.accountFormOpen = false; this.accountForm = emptyForm(); this.actionError = ''; },
    async cancelWithdrawal(withdrawal) { if (!withdrawal?.id || this.processingWithdrawalId || !window.confirm('Hủy yêu cầu rút tiền này?')) return; this.processingWithdrawalId = withdrawal.id; this.actionError = ''; try { await walletService.cancelWithdrawal(withdrawal.id); await this.loadWallet(); } catch (error) { this.actionError = error.message || 'Không thể hủy yêu cầu.'; } finally { this.processingWithdrawalId = null; } },
    money(value) { return new Intl.NumberFormat('vi-VN', { style: 'currency', currency: 'VND', maximumFractionDigits: 0 }).format(Number(value || 0)); },
    formatDate(value) { return value ? new Date(value).toLocaleString('vi-VN') : '-'; },
    statusLabel(status) { return { active: 'Đang hoạt động', locked: 'Đang khóa', suspended: 'Tạm ngưng' }[status] || status; },
    typeLabel(type) { return { deposit: 'Nạp tiền', payment: 'Thanh toán booking', refund: 'Hoàn tiền', withdrawal: 'Rút tiền', adjustment: 'Điều chỉnh' }[type] || 'Biến động số dư'; },
  },
};
</script>

<style scoped>
